// قياس ومراقبة TTFB بدقة باستخدام Performance Navigation Timing API
const [navEntry] = performance.getEntriesByType('navigation') as PerformanceNavigationTiming[];

if (navEntry) {
  // وقت معالجة السيرفر وشبكة الاتصال من بداية إرسال الطلب
  const serverTtfb = navEntry.responseStart - navEntry.requestStart;

  // إجمالي وقت TTFB الشامل من لحظة بدء التنقل (Navigation Start)
  const totalTtfb = navEntry.responseStart - navEntry.startTime;

  console.log(`Backend & Network TTFB: ${serverTtfb.toFixed(2)} ms`);
  console.log(`Total Navigation TTFB: ${totalTtfb.toFixed(2)} ms`);
}

// مراقبة الدخول غير المتزامن باستخدام PerformanceObserver
const observer = new PerformanceObserver((list) => {
  list.getEntriesByType('navigation').forEach((entry) => {
    const nav = entry as PerformanceNavigationTiming;
    console.log('Real-time TTFB:', nav.responseStart - nav.requestStart);
  });
});
observer.observe({ type: 'navigation', buffered: true });
